// Approving a swap also refuses every other still-pending request for the same shift.
const decideSwapOnce = Rota.prototype.decideSwap;

Rota.prototype.decideSwap = function (
  this: Rota,
  swapId: string,
  approve: boolean,
  at: number,
): SwapRequest {
  // If this throws, nothing has been changed yet, so no request is touched.
  const result = decideSwapOnce.call(this, swapId, approve, at);
  if (approve) {
    const swaps = (this as unknown as { swaps: SwapRequest[] }).swaps;
    const approved = swaps.find((s) => s.id === swapId) ?? result;
    for (const other of swaps) {
      if (
        other.id !== approved.id &&
        other.shiftId === approved.shiftId &&
        other.status === "pending"
      ) {
        other.status = "refused";
        other.decidedAt = approved.decidedAt;
      }
    }
  }
  return result;
};
